/**
 * Asset manifest. Files under public/assets/gen/ are generated by the orchestrator and may be missing
 * at any time; every consumer must fall back gracefully (Assets returns null).
 */
export interface ModelEntry {
  path: string;
  /** Height in metres after normalisation. */
  height: number;
  /** Extra yaw (radians) so the normalised model faces +Z. */
  yawOffset: number;
}

export const MODELS = {
  scotty: { path: 'assets/gen/models/scotty.glb', height: 0.9, yawOffset: 0 },
  beaver: { path: 'assets/gen/models/beaver.glb', height: 1.6, yawOffset: 0 },
  tree: { path: 'assets/gen/models/tree.glb', height: 2.6, yawOffset: 0 },
  bear: { path: 'assets/gen/models/bear.glb', height: 2.0, yawOffset: 0 },
  collie: { path: 'assets/gen/models/collie.glb', height: 1.5, yawOffset: 0 },
  wasp: { path: 'assets/gen/models/wasp.glb', height: 1.5, yawOffset: 0 },
  tiger: { path: 'assets/gen/models/tiger.glb', height: 1.8, yawOffset: 0 },
  dean: { path: 'assets/gen/models/dean.glb', height: 4.5, yawOffset: 0 },
} satisfies Record<string, ModelEntry>;

